    /** The pre-selected country on the sign-in screen. */
    val defaultCountry: CountryCode = all.first()

    fun byIso2(iso2: String): CountryCode? = all.firstOrNull { it.iso2 == iso2 }

    /**
     * Longest-prefix decomposition for a full E.164 number pasted into the
     * national-number field: "919876543210" -> (India, "9876543210"). Ties
     * among equal-length dial codes (NANP "1", "44", ...) prefer the
     * [primaryDialOwner] — the recomposed E.164 is identical either way.
     * Null when [digits] matches no dial code.
     */
    fun longestDialPrefix(digits: String): Pair<CountryCode, String>? {
        var best: CountryCode? = null
        for (c in all) {
            if (!digits.startsWith(c.dialCode)) continue
            val b = best
            when {
                b == null -> best = c
                c.dialCode.length > b.dialCode.length -> best = c
                c.dialCode.length == b.dialCode.length &&
                    primaryDialOwner[c.dialCode] == c.iso2 &&
                    primaryDialOwner[b.dialCode] != b.iso2 -> best = c
            }
        }
        return best?.let { it to digits.substring(it.dialCode.length) }
    }

    /** Tie-break preference for shared dial codes (see longestDialPrefix). */
    private val primaryDialOwner = mapOf(
        "1" to "US",
        "7" to "RU",
        "44" to "GB",
        "47" to "NO",
        "61" to "AU",
        "262" to "RE",
        "358" to "FI",
        "590" to "GP",
        "672" to "NF",
    )
